CREATE OR REPLACE FUNCTION public.creator_activity()
 RETURNS TABLE(id uuid, last_sign_in_at timestamp with time zone, last_seen_at timestamp with time zone, last_posted_at timestamp with time zone, last_active_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
